/* v38: viewer identities, searchable content, public community and reliable local chat. */
(()=>{
'use strict';const F=window.F,e=F.e,old={catalog:F.catalog,channel:F.channel,chat:F.chat,navigate:F.navigate,render:F.render,read:F.readUrl,write:F.writeUrl,share:F.modals.share,info:F.modals.info,close:F.closeModal};
const S=F.v38Viewer={contentMap:new Map(),activeId:null,intent:null,pages:{},rooms:new Map(),mounted:null,sent:new Map(),faults:{},report:null,clip:null,posts:new Map(),postId:null,commentPages:{},commentDrafts:new Map(),positions:new Map(),volume:80,qualityOrigin:null,accessReason:'private',dialog:null};
const route=r=>r.kind==='live'?'watch':r.kind==='clip'?'clip-watch':'vod-watch',channel=()=>Math.max(0,Math.min(F.broadcasts.length-1,Number(F.selectedBroadcast)||0));
const node=html=>{const n=document.createElement('div');n.innerHTML=html;return n;},btn=(t,a,i='',c='',attrs='')=>F.btn(t,'v38-viewer-'+a,i,c,attrs),stop=ev=>{ev.preventDefault();ev.stopImmediatePropagation();};
const clock=n=>[Math.floor(n/3600),Math.floor(n/60)%60,Math.floor(n)%60].map(x=>String(x).padStart(2,'0')).join(':'),date=t=>new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'long',day:'numeric'}).format(new Date(t));
const parse=s=>{const p=String(s).trim().split(':');return p.length>=2&&p.length<=3&&p.every(x=>/^\d{1,2}$/.test(x))&&p.slice(1).every(x=>+x<60)?p.reduce((n,x)=>n*60+Number(x),0):NaN;};
function register(r){S.contentMap.set(r.id,r);return r;}
const names={code:['작은 기능 하나씩 완성하기','함께 만드는 화면, 첫 번째 테스트','작업실 정리와 다음 목표','작업 화면을 공유하는 방법','한 줄씩 고치는 플레이어','이번 주의 개발 기록'],design:['빛과 색을 담는 드로잉','새로운 브러시로 그려보는 오후','한 장의 그림이 완성되기까지','색을 고르는 시간','작업실에서 만난 풍경','다시 꺼내 본 스케치'],night:['비 오는 도시의 밤','음악과 함께 달리는 길','차분한 저녁 플레이리스트','늦은 밤의 산책','주말의 드라이브','조용한 오후'],game:['새로운 지역을 찾아서','함께 도전하는 오늘의 목표','모험을 마치고 돌아오는 길','처음 만나는 보스','작은 섬에서의 하루','다음 여정을 준비해요']};
F.broadcasts.forEach((b,i)=>{register({id:'live-'+i,channelIndex:i,kind:'live',title:b.title,publishedAt:new Date(Date.now()-i*37*60000).toISOString(),duration:10800,views:b.viewers,status:'available'});const ts=names[b.scene]||names.code;
ts.forEach((title,j)=>register({id:'vod-'+i+'-'+j,channelIndex:i,kind:'vod',title,publishedAt:new Date(Date.now()-(j+1)*86400000-i*3600000).toISOString(),duration:[8076,6492,11325][j%3],views:1284+(i*251+j*137)%4321,status:'available',ordinal:j}));
ts.slice(0,4).forEach((title,j)=>register({id:'clip-'+i+'-'+j,channelIndex:i,kind:'clip',title:title+' — 기억하고 싶은 순간',publishedAt:new Date(Date.now()-(j+1)*43200000-i*3600000).toISOString(),duration:42,views:312+i*173+j*43,status:'available',originalId:'vod-'+i+'-'+j,ordinal:j}));
S.posts.set(i,Array.from({length:28},(_,j)=>({id:'post-'+i+'-'+j,title:j===0?'이번 주 방송 안내':'작업실 이야기 '+(j+1),body:j===0?'새로 만든 화면을 함께 살펴볼 예정이에요.\n목요일 오후 8시에 만나요.':'함께 나누고 싶은 작업 과정을 기록했어요.\n여러분의 생각을 댓글로 남겨주세요.',publishedAt:new Date(Date.now()-j*86400000).toISOString(),pinned:j===0,status:j===8?'deleted':j===12?'members':'available',comments:j===0?Array.from({length:35},(_,k)=>({id:'comment-'+k,name:['모아','파도','산책'][k%3],text:k===2?'이 댓글은 삭제됐어요.':'다음 방송도 기대할게요. '+(k+1),deleted:k===2})):[]})));});
function persistContent(){try{sessionStorage.setItem('frame.v38.content.records',JSON.stringify([...S.contentMap.values()].filter(r=>r.id.startsWith('clip-created-')||r.id.startsWith('history-'))));}catch{}}
try{const records=JSON.parse(sessionStorage.getItem('frame.v38.content.records')||'[]');if(Array.isArray(records))records.filter(r=>r&&typeof r.id==='string'&&typeof r.title==='string'&&['live','vod','clip'].includes(r.kind)&&Number.isInteger(r.channelIndex)&&r.channelIndex>=0&&r.channelIndex<F.broadcasts.length&&Number.isFinite(r.duration)&&r.duration>=0&&Number.isFinite(Date.parse(r.publishedAt))).forEach(register);}catch{}
function current(){return S.contentMap.get(S.activeId)||S.contentMap.get('live-'+channel());}
function select(r){if(!r)return;S.activeId=r.id;F.selectedBroadcast=r.channelIndex;F.v33Viewer.record=r.kind==='live'?null:{index:r.channelIndex,title:r.title,id:r.id};}
function contentIdFor(kind,index,ordinal=0){return kind==='live'?'live-'+index:kind+'-'+index+'-'+ordinal;}
function openContent(id){const r=S.contentMap.get(id);if(!r)return false;S.intent=id;select(r);F.navigate(route(r));return true;}
function publishClip(d){const r=S.contentMap.get(d.originalId)||current();return register({id:'clip-created-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),kind:'clip',channelIndex:r.channelIndex,title:d.title,publishedAt:new Date().toISOString(),duration:d.end-d.start,views:0,status:'available',originalId:r.id,start:d.start,end:d.end});}
function room(key){if(!S.rooms.has(key))S.rooms.set(key,{draft:'',reply:null,mode:'open',pending:[],tokens:new Map()});return S.rooms.get(key);}
const chatKey=()=>String(F.currentBase==='studio'?0:channel());
Object.assign(S,{current,openContent,publishClip,contentIdFor,chatRoom:room,setFault(key,v=true){S.faults[key]=v;},setChatMode(index,mode){room(String(index)).mode=mode;F.render();},setAccessReason(value){S.accessReason=value;F.render();}});
function card(r){const h=node(F.card(F.broadcasts[r.channelIndex],r.ordinal||0,r.kind==='live'?'live':r.kind==='clip'?'clip':'vod')),c=h.firstElementChild;c.dataset.v38Content=r.id;
c.querySelectorAll('[data-go]').forEach(x=>{x.dataset.broadcast=r.channelIndex;if(['watch','vod-watch','clip-watch'].includes(x.dataset.go)){x.dataset.v38Content=r.id;x.dataset.go=route(r);}});
const t=c.querySelector('.card-title');if(t){t.textContent=r.title;t.title=r.title;}c.querySelector('.thumb')?.setAttribute('aria-label',r.title+' 재생하기');const d=c.querySelector('.duration');if(d)d.textContent=clock(r.duration);
const m=c.querySelector('.card-category');if(m&&r.kind!=='live')m.innerHTML='<span>조회수 '+r.views.toLocaleString('ko-KR')+'회</span><span class="v35-meta-separator" aria-hidden="true">·</span><time datetime="'+e(r.publishedAt)+'">'+date(r.publishedAt)+'</time>';return h.innerHTML;}
function pager(key,count,page,size){return '<div class="v38-pagination"><span>'+(!count?0:page*size+1)+'–'+Math.min((page+1)*size,count)+' / '+count.toLocaleString()+'개</span><div>'+btn('이전','page','arrow','small','data-key="'+e(key)+'" data-page="'+(page-1)+'" '+(page===0?'disabled':''))+btn('다음','page','right','small','data-key="'+e(key)+'" data-page="'+(page+1)+'" '+((page+1)*size>=count?'disabled':''))+'</div></div>';}
const ordered=(a,sort)=>a.slice().sort(sort==='인기순'?(a,b)=>b.views-a.views||Date.parse(b.publishedAt)-Date.parse(a.publishedAt):(a,b)=>Date.parse(b.publishedAt)-Date.parse(a.publishedAt)||a.id.localeCompare(b.id));
function results(rows,key,size=18){const page=Math.min(Math.max(0,S.pages[key]||0),Math.max(0,Math.ceil(rows.length/size)-1));S.pages[key]=page;return rows.length?'<div class="catalog-grid v3-grid">'+rows.slice(page*size,(page+1)*size).map(card).join('')+'</div>'+pager(key,rows.length,page,size):F.empty('조건에 맞는 영상이 없어요','','','','search');}
function search(state){const q=String(F.searchQuery||'').trim(),norm=s=>String(s).normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,''),match=s=>norm(s).includes(norm(q));if(!q)return old.catalog('search',state);const type=F.searchType||'전체';
const form='<form class="v3-mobile-search" id="catalog-search" role="search"><input name="query" type="search" maxlength="120" aria-label="방송 및 채널 검색" placeholder="방송 및 채널 검색" value="'+e(q)+'"><button aria-label="검색" type="submit">'+F.icon('search')+'</button></form>',tabs='<div class="v38-filter-tabs" role="tablist" aria-label="검색 결과 유형">'+['전체','라이브','채널','다시보기','클립'].map(t=>btn(t,'search-type','','','role="tab" aria-selected="'+(type===t)+'" tabindex="'+(type===t?0:-1)+'" data-type="'+t+'"')).join('')+'</div>';
const channels=F.broadcasts.map((b,i)=>({b,i})).filter(({b})=>match(b.name+' '+b.category)),records=[...S.contentMap.values()].filter(r=>r.status==='available'&&match(r.title+' '+F.broadcasts[r.channelIndex].name)),sections=[];
if(['전체','채널'].includes(type)&&channels.length){const key='search-channel-'+q,page=S.pages[key]||0,size=type==='전체'?4:12;sections.push('<section class="search-section"><div class="v3-section-heading"><h2>채널 <small>'+channels.length+'</small></h2>'+(type==='전체'&&channels.length>4?btn('모두 보기','search-type','right','ghost small','data-type="채널"'):'')+'</div><div class="search-channel-list">'+channels.slice(page*size,(page+1)*size).map(({b,i})=>'<button class="search-channel" data-go="channel" data-broadcast="'+i+'">'+F.avatar(b.initial,'round')+'<span><strong>'+e(b.name)+'</strong><small>'+e(b.category)+'</small></span></button>').join('')+'</div>'+(type==='채널'?pager(key,channels.length,page,size):'')+'</section>');}
for(const [label,kind]of [['라이브','live'],['다시보기','vod'],['클립','clip']])if(type==='전체'||type===label){const rows=ordered(records.filter(r=>r.kind===kind),'최신순');if(rows.length)sections.push('<section class="search-section"><div class="v3-section-heading"><h2>'+label+' <small>'+rows.length+'</small></h2>'+(type==='전체'&&rows.length>4?btn('모두 보기','search-type','right','ghost small','data-type="'+label+'"'):'')+'</div>'+(type==='전체'?'<div class="catalog-grid v3-grid">'+rows.slice(0,4).map(card).join('')+'</div>':results(rows,'search-'+kind+'-'+q))+'</section>');}
return '<div class="v3-catalog v38-catalog">'+form+'<div class="v3-section-heading"><h1>‘'+e(q)+'’ 검색 결과</h1></div>'+tabs+(state==='검색 결과 없음'||!sections.length?F.empty('검색 결과가 없어요','검색어나 콘텐츠 종류를 바꿔보세요.','검색어 지우기','v38-viewer-clear-search','search'):sections.join(''))+'</div>';}
F.catalog=(id,state)=>{if(id==='search')return search(state);if(!['vod','clips'].includes(id)||state!=='기본')return old.catalog(id,state);const kind=id==='vod'?'vod':'clip',sort=F.v33Viewer.sort[id]||'최신순';return '<div class="v3-catalog v38-catalog"><div class="v3-section-heading"><h1>'+(kind==='vod'?'다시보기':'클립')+'</h1>'+btn(sort,'sort','chevron','ghost','data-kind="'+id+'" aria-haspopup="listbox"')+'</div>'+results(ordered([...S.contentMap.values()].filter(r=>r.kind===kind&&r.status==='available'),sort),id)+'</div>';};
function decorate(scope){scope.querySelectorAll('.v3-card:not([data-v38-content])').forEach(c=>{if(c.closest('.v3-recent'))return;const i=Number(c.querySelector('[data-broadcast]')?.dataset.broadcast||channel()),kind=c.querySelector('[data-go="clip-watch"]')?'clip':c.querySelector('[data-go="vod-watch"]')?'vod':'live',title=c.querySelector('.card-title')?.textContent.trim(),r=[...S.contentMap.values()].find(r=>r.channelIndex===i&&r.kind===kind&&r.title===title)||S.contentMap.get(contentIdFor(kind,i));if(r){c.dataset.v38Content=r.id;c.querySelectorAll('[data-go="'+route(r)+'"]').forEach(x=>x.dataset.v38Content=r.id);}});}
function community(i){const all=S.posts.get(i)||[],p=all.find(p=>p.id===S.postId),key='posts-'+i,page=S.pages[key]||0;
if(!p)return '<section class="v38-posts"><div class="v3-section-heading"><h2>게시글</h2><span>'+all.length+'개</span></div>'+all.slice(page*10,(page+1)*10).map(p=>'<button class="v38-post-row" data-action="v38-viewer-post-open" data-id="'+e(p.id)+'"><div>'+(p.pinned?'<span class="v38-post-pin">공지</span>':'')+'<strong>'+e(p.title)+'</strong></div><p>'+e(p.status==='deleted'?'삭제된 게시글':p.body.split('\n')[0])+'</p><span>'+date(p.publishedAt)+(p.comments.length?'　댓글 '+p.comments.length:'')+'</span></button>').join('')+pager(key,all.length,page,10)+'</section>';
const restricted=p.status==='members'&&!F.v38Shared?.memberships?.some(m=>m.channelId===channel()&&m.user===String(F.accountDesign?.savedProfile?.id||'viewer-self')&&['이용 중','갱신 예정','해지 예약'].includes(m.status)),unavailable=p.status==='deleted'||restricted,cp=S.commentPages[p.id]||0;
return '<section class="v38-post-detail">'+btn('게시글 목록','post-back','arrow','ghost')+'<h2>'+e(p.title)+'</h2><time>'+date(p.publishedAt)+'</time>'+(unavailable?F.empty(p.status==='deleted'?'삭제된 게시글이에요':'멤버만 볼 수 있는 게시글이에요','',restricted?'멤버십 보기':'목록으로',restricted?'go:membership':'v38-viewer-post-back','shield'):'<p class="v38-post-body">'+e(p.body)+'</p><div class="v38-comments"><h3>댓글 '+p.comments.length+'</h3>'+p.comments.slice(cp*10,(cp+1)*10).map(c=>'<article class="v38-comment"><strong>'+e(c.name)+'</strong><p>'+e(c.text)+'</p>'+(!c.deleted?(F.sessionLoggedIn&&c.authorId===String(F.accountDesign?.savedProfile?.id||'viewer-self')?btn('삭제','comment-delete','','ghost small','data-id="'+e(c.id)+'"'):btn('신고','report-comment','','ghost small','data-id="'+e(c.id)+'"')):'')+'</article>').join('')+(p.comments.length>10?'<div class="v38-pagination"><span>'+(cp+1)+' / '+Math.ceil(p.comments.length/10)+'</span>'+btn('이전','comments-page','arrow','small','data-page="'+(cp-1)+'" '+(cp===0?'disabled':''))+btn('다음','comments-page','right','small','data-page="'+(cp+1)+'" '+((cp+1)*10>=p.comments.length?'disabled':''))+'</div>':'')+(F.sessionLoggedIn?'<form id="v38-comment-form"><label class="sr-only" for="v38-comment">댓글</label><textarea id="v38-comment" maxlength="500" rows="2" placeholder="댓글을 남겨보세요.">'+e(S.commentDrafts.get(p.id)||'')+'</textarea><div class="v38-form-actions">'+btn('취소','comment-clear','','ghost')+'<button type="submit" class="primary">댓글 쓰기</button></div><p id="v38-comment-error" class="error-text" role="alert" hidden></p></form>':F.go('login','로그인하고 댓글 쓰기','user'))+'</div>')+'</section>';}
F.channel=state=>{const h=node(old.channel(state)),tabs=h.querySelector('.page-tabs');if(state==='접근 제한'){let n=tabs?.nextElementSibling;while(n){const next=n.nextElementSibling;n.remove();n=next;}const reason=!F.sessionLoggedIn?'login':S.accessReason;tabs?.insertAdjacentHTML('afterend',F.empty(reason==='login'?'로그인이 필요한 채널이에요':reason==='expired'?'시청 권한이 만료됐어요':'공개 대상에 포함되지 않은 채널이에요','',reason==='login'?'로그인':'다른 방송 보기',reason==='login'?'go:login':'go:live','shield'));return h.innerHTML;}
if(tabs){tabs.insertAdjacentHTML('beforeend',btn('게시글','channel-posts','',''+(F.channelTab==='게시글'?'active':''),'aria-pressed="'+(F.channelTab==='게시글')+'"'));
if(F.channelTab==='게시글'){tabs.querySelectorAll('[data-action="v2-channel-tab"]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});let n=tabs.nextElementSibling;while(n){const next=n.nextElementSibling;n.remove();n=next;}tabs.insertAdjacentHTML('afterend',community(channel()));}
else if(['다시보기','클립'].includes(F.channelTab)){const target=tabs.nextElementSibling;if(target)target.outerHTML='<section class="search-section">'+results(ordered([...S.contentMap.values()].filter(r=>r.channelIndex===channel()&&r.kind===(F.channelTab==='클립'?'clip':'vod')),'최신순'),'channel-'+channel()+'-'+F.channelTab)+'</section>';}}
decorate(h);return h.innerHTML;};
F.modals.share=state=>{const c=old.share(state),h=node(c.body),r=current(),input=h.querySelector('#share-link');if(input){const u=new URL(location.href);u.search='';for(const [k,v]of Object.entries({screen:route(r),device:'desktop',state:'기본',channel:'channel-'+r.channelIndex,content:r.id}))u.searchParams.set(k,v);if(F.values['share-option']==='현재 재생 시점부터'){const t=Number(F.root.querySelector('#timeline')?.value||0);if(t>0)u.searchParams.set('t',String(Math.min(r.duration,Math.floor(t))));}input.value=u.toString();input.setAttribute('value',u.toString());}const t=h.querySelector('.v31-share-summary strong');if(t)t.textContent=r.title;c.body=h.innerHTML;return c;};
F.modals.info=state=>{const c=old.info(state),h=node(c.body),t=h.querySelector('.v31-viewer-info-content>h3');if(t)t.textContent=current().title;c.body=h.innerHTML;return c;};
function captureChat(){const input=F.root.querySelector('#chat-message');if(input&&S.mounted!==null)room(S.mounted).draft=input.value;}
F.chat=()=>{captureChat();const key=chatKey(),r=room(key),prev=F.root.querySelector('#chat-message');if(prev)prev.value=r.draft;F.chatDraft=r.draft;const h=node(old.chat()),panel=h.querySelector('.v34-chat');S.mounted=key;if(!panel)return h.innerHTML;panel.dataset.v38Room=key;panel.querySelector('.chat-head')?.insertAdjacentHTML('beforeend',btn('','participants','user','icon ghost','aria-label="채팅 참여자"'));const input=h.querySelector('#chat-message'),form=h.querySelector('#chat-form');
if(form)form.id='v38-chat-form';
if(input){input.value=r.draft;input.textContent=r.draft;input.disabled=r.mode!=='open';if(r.mode!=='open'){input.placeholder={reconnecting:'채팅에 다시 연결하고 있어요',followers:'팔로워만 채팅할 수 있어요',restricted:'채팅 참여가 제한됐어요',ended:'종료된 방송의 채팅이에요'}[r.mode]||'지금은 채팅할 수 없어요';form.insertAdjacentHTML('beforebegin','<div class="v38-chat-notice" role="status">'+e(input.placeholder)+(r.mode==='reconnecting'?btn('다시 연결','chat-reconnect','','ghost small'):r.mode==='followers'?btn('팔로우','chat-follow','heart','ghost small'):'')+'</div>');}form?.querySelector('.v34-chat-name-change')?.insertAdjacentHTML('afterend',btn('','emoji','smile','icon ghost','aria-label="이모티콘"'));if(r.reply)form.insertAdjacentHTML('afterbegin','<div class="v38-chat-reply"><span><strong>'+e(r.reply.name)+' 님에게 답글</strong><small>'+e(r.reply.text)+'</small></span>'+btn('','reply-cancel','close','icon ghost','aria-label="답글 취소"')+'</div>');}
h.querySelectorAll('.chat-line').forEach((l,i)=>{l.dataset.v38Line=i;l.insertAdjacentHTML('beforeend',btn('','message-menu','more','v38-chat-line-menu icon ghost','data-line="'+i+'" aria-label="메시지 메뉴"'));});const log=h.querySelector('.chat-messages');r.pending.forEach(m=>log?.insertAdjacentHTML('beforeend','<div class="chat-line v38-chat-pending" data-message-id="'+e(m.id)+'"><strong>'+e(m.name)+'</strong><span>'+e(m.text)+'</span><small role="status">'+(m.status==='sending'?'전송 중':m.status==='failed'?'전송 실패':'확인 중')+'</small>'+(m.status!=='sending'?btn('재전송','message-retry','','ghost small','data-id="'+e(m.id)+'"'):'')+'</div>'));return h.innerHTML;};
function send(text,reply,retryId){const key=chatKey(),r=room(key),id=retryId||'message-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);if(r.mode!=='open')return;let m=r.pending.find(m=>m.id===id);if(m?.status==='sending')return;if(!m){m={id,text,name:F.nickname,reply,status:'sending'};r.pending.push(m);}m.status='sending';const token=Symbol();r.tokens.set(id,token);F.render();setTimeout(()=>{if(r.tokens.get(id)!==token)return;const fault=S.faults.chat;delete S.faults.chat;if(fault){m.status=fault==='unknown'?'unknown':'failed';if(key===chatKey())F.render();return;}r.pending=r.pending.filter(m=>m.id!==id);const c=F.v34Chat.channels.get(key)||{messages:[],authors:[]};if(!S.sent.has(id)){c.messages.push(text);c.authors.push(m.name);F.v34Chat.channels.set(key,c);S.sent.set(id,{...m,channel:key,status:'sent'});}if(key===chatKey()){F.sessionMessages=c.messages;F.render();}},650);}
function dialog(title,body,footer,kind){S.dialog=kind;S.returnFocus=document.activeElement?.id;F.genericDialog(title,body,'확인');F.dialog.classList.add('v38-viewer-dialog');F.dialog.querySelector('.modal-footer').innerHTML=footer;F.labelControls(F.dialog);}
function participants(){dialog('채팅 참여자','<div class="v38-participants">'+[...new Set([F.broadcasts[channel()].name,F.nickname,'파도','모아','산책'])].map((n,i)=>'<div>'+F.avatar(n,'round')+'<span>'+e(n)+(i===0?'<small>방송자</small>':'')+'</span>'+btn('언급','mention','','ghost small','data-name="'+e(n)+'"')+'</div>').join('')+'</div>',btn('닫기','dialog-close'),'participants');}
function target(m){const r=current();return {id:m?.id||r.id,title:m?m.name+' 님의 메시지':r.title,detail:m?.text||F.broadcasts[r.channelIndex].name,kind:m?'메시지':r.kind==='live'?'라이브':r.kind==='clip'?'클립':'다시보기',channelIndex:r.channelIndex};}
function beginReport(t){S.report={target:t||target(),reason:'',detail:'',status:'draft',error:'',id:'report-'+Date.now()};F.navigate('report-content');}
function field(label,id,value,area=false,max=1000){return '<div class="field"><label for="'+id+'">'+label+'</label>'+(area?'<textarea id="'+id+'" rows="4" maxlength="'+max+'">'+e(value)+'</textarea>':'<input id="'+id+'" value="'+e(value)+'" maxlength="'+max+'" autocomplete="off">')+'</div>';}
F.modals['report-content']=state=>{const d=S.report||(S.report={target:target(),reason:'',detail:'',status:state==='접수 완료'?'sent':'draft',error:'',id:'report-direct'}),summary='<div class="v38-target"><small>'+e(d.target.kind)+'</small><strong>'+e(d.target.title)+'</strong><span>'+e(d.target.detail)+'</span></div>';if(d.status==='sending')return {title:'신고하기',body:summary+'<div class="v38-progress" role="status" aria-busy="true"><span class="spinner"></span>신고를 접수하고 있어요.</div>',footer:btn('닫기','close-report'),cls:'medium'};if(d.status==='sent')return {title:'신고하기',body:summary+'<div class="v38-result">'+F.icon('check')+'<h3>신고가 접수됐어요.</h3><p>접수 번호 '+e(d.id)+'</p></div>',footer:btn('닫기','close-report'),cls:'medium'};const failed=['failed','unknown'].includes(d.status);return {title:'신고하기',body:summary+(failed?'<p class="v38-inline-error" role="alert">'+(d.status==='unknown'?'접수 결과를 확인하지 못했어요. 같은 신고를 다시 보내기 전에 상태를 확인하세요.':'신고를 접수하지 못했어요. 작성 내용은 유지했어요.')+'</p>':'')+'<form id="v38-report-form">'+F.field('신고 사유',btn(d.reason||'사유 선택','report-reason','chevron','choice-button','aria-haspopup="listbox"'))+field('상세 내용'+(d.reason==='기타'?'':' (선택)'),'v38-report-detail',d.detail,true)+'<p class="error-text" id="v38-report-error" role="alert" '+(d.error?'':'hidden')+'>'+e(d.error)+'</p></form>',footer:btn('취소','close-report')+(d.status==='unknown'?btn('접수 상태 확인','report-status','','primary'):'<button type="submit" form="v38-report-form" class="primary">'+(failed?'다시 접수':'신고 접수')+'</button>'),cls:'medium'};};
function beginClip(){const r=current(),end=r.kind==='live'?Number(F.root.querySelector('#timeline')?.max||r.duration):r.duration,start=Math.max(0,Math.min(Math.floor(Number(F.root.querySelector('#timeline')?.value)||0),end-1));S.clip={source:{start:0,end,id:r.id,title:r.title},title:'',start:clock(start),end:clock(Math.min(start+30,end)),duration:Math.min(30,end-start),status:'draft',error:'',createdId:null,token:0};}
F.modals['clip-create']=()=>{const d=S.clip||(beginClip(),S.clip);if(d.status==='processing')return {title:'클립 만들기',body:'<div class="v38-progress" role="status" aria-busy="true"><span class="spinner"></span>클립을 만들고 있어요.</div>',footer:btn('취소','clip-cancel'),cls:'medium'};if(d.status==='done')return {title:'클립 만들기',body:'<div class="v38-result">'+F.icon('check')+'<h3>클립이 만들어졌어요.</h3><p>'+e(d.title)+'</p></div>',footer:btn('닫기','clip-cancel')+btn('클립 보기','clip-watch','','primary'),cls:'medium'};return {title:'클립 만들기',body:'<div class="v38-target"><small>원본 영상</small><strong>'+e(d.source.title)+'</strong><span>'+clock(d.source.start)+' – '+clock(d.source.end)+'</span></div>'+(d.status==='failed'?'<p class="v38-inline-error" role="alert">클립을 만들지 못했어요. 구간과 제목은 유지했어요.</p>':'')+'<form id="v38-clip-form"><div class="v38-time-pair">'+field('시작','v38-clip-start',d.start,false,8)+field('종료','v38-clip-end',d.end,false,8)+'</div><div class="v38-clip-duration"><label for="v38-clip-duration">구간 길이</label><output>'+d.duration+'초</output><input id="v38-clip-duration" type="range" min="1" max="60" value="'+d.duration+'"></div>'+field('클립 제목','v38-clip-title',d.title,false,80)+'<p id="v38-clip-error" class="error-text" role="alert" '+(d.error?'':'hidden')+'>'+e(d.error)+'</p></form>',footer:btn('취소','clip-cancel')+'<button type="submit" form="v38-clip-form" class="primary">'+(d.status==='failed'?'다시 만들기':'클립 만들기')+'</button>',cls:'medium'};};
F.render=()=>{captureChat();old.render();decorate(F.root);const r=current();if(['watch','vod-watch','clip-watch'].includes(F.currentBase)){const h=F.root.querySelector('.v3-watch-meta h1');if(h)h.textContent=r.title;if(r.status!=='available'){const player=F.root.querySelector('#video-player');if(player)player.replaceWith(node(F.empty(r.status==='private'?'비공개 영상이에요':r.status==='deleted'?'삭제된 영상이에요':'영상을 찾을 수 없어요','','다시보기 둘러보기','go:vod','video')).firstElementChild);}if(F.v38Account?.preferencesIntent?.resume===false&&F.v37History)F.v37History.resumeIntent=null;}if(S.dialog&&!F.dialog.open)S.dialog=null;};
F.navigate=(id,state,replace=false)=>{if(F.screen==='report-content'&&id!=='report-content')S.report=null;if(F.screen==='clip-create'&&id!=='clip-create'){if(S.clip)S.clip.token++;S.clip=null;}if(id==='quality'&&['watch','vod-watch','clip-watch'].includes(F.screen))S.qualityOrigin=F.screen;if(id==='watch'&&F.screen==='quality')id=S.qualityOrigin||route(current());captureChat();if(id==='report-content'&&F.screen!==id&&!S.report)S.report={target:target(),reason:'',detail:'',status:'draft',error:'',id:'report-'+Date.now()};if(id==='clip-create'&&F.screen!==id)beginClip();if(['watch','vod-watch','clip-watch'].includes(id)){let r=S.contentMap.get(S.intent);S.intent=null;const H=F.v37History,hr=H?.records.find(r=>r.id===H.resumeIntent?.recordId);if(!r&&hr&&(F.screen==='history'||F.root.querySelector('[data-action="v37-history-play"]:focus')))r=register({id:'history-'+hr.videoId,channelIndex:hr.channelIndex,title:hr.title,kind:hr.kind==='클립'?'clip':hr.kind==='라이브'?'live':'vod',publishedAt:hr.watchedAt,duration:hr.duration,views:1284,status:hr.status});if(!r&&route(current())===id&&current().channelIndex===channel()&&(F.modalScreens.has(F.screen)||F.screen===id||F.screen==='quality'))r=current();select(r||S.contentMap.get(contentIdFor(id==='watch'?'live':id==='clip-watch'?'clip':'vod',channel())));if(F.v38Account?.preferencesIntent?.autoplay===false)F.playing=false;}if(id==='channel'&&F.screen!=='channel')S.postId=null;const key=String(id==='studio'?0:channel());if(S.mounted!==null&&key!==S.mounted){F.chatDraft=room(key).draft;const input=F.root.querySelector('#chat-message');if(input)input.value=F.chatDraft;S.mounted=key;}return old.navigate(id,state,replace);};
F.writeUrl=replace=>{persistContent();try{old.write(replace);}catch(error){if(error.name!=='SecurityError')throw error;}const u=new URL(location.href),base=F.screen==='quality'?S.qualityOrigin||route(current()):F.modalScreens.has(F.screen)?F.currentBase:F.screen;if(['channel','watch','vod-watch','clip-watch'].includes(base)){u.searchParams.set('channel','channel-'+channel());if(base!=='channel')u.searchParams.set('content',current().id);else{u.searchParams.delete('content');if(F.channelTab)u.searchParams.set('tab',F.channelTab);}}else{u.searchParams.delete('content');u.searchParams.delete('channel');u.searchParams.delete('tab');}try{history.replaceState({},'',u);}catch{};};
F.readUrl=()=>{old.read();const p=new URL(location.href).searchParams,ci=p.get('channel')?.match(/^channel-(\d+)$/);if(ci&&Number(ci[1])<F.broadcasts.length)F.selectedBroadcast=Number(ci[1]);const r=S.contentMap.get(p.get('content'));if(r)select(r);else if(p.get('content')&&['watch','vod-watch','clip-watch'].includes(F.screen))select(register({id:p.get('content').slice(0,160),title:'찾을 수 없는 영상',channelIndex:channel(),kind:F.screen==='watch'?'live':F.screen==='clip-watch'?'clip':'vod',publishedAt:new Date().toISOString(),duration:0,views:0,status:'missing'}));else if(['watch','vod-watch','clip-watch'].includes(F.screen))select(S.contentMap.get(contentIdFor(F.screen==='watch'?'live':F.screen==='clip-watch'?'clip':'vod',channel())));if(F.screen==='channel'&&['홈','다시보기','클립','방송 일정','정보','게시글'].includes(p.get('tab')))F.channelTab=p.get('tab');};
F.closeModal=()=>{const own=S.dialog,focus=S.returnFocus;S.dialog=null;const v=old.close();if(own&&focus)requestAnimationFrame(()=>document.getElementById(focus)?.focus({preventScroll:true}));return v;};
window.addEventListener('input',ev=>{const i=ev.target;if(i.id==='v38-comment')S.commentDrafts.set(S.postId,i.value);if(i.id==='chat-message'&&i.closest('.v34-chat')){const r=room(i.closest('[data-v38-room]')?.dataset.v38Room||chatKey());r.draft=i.value;const send=i.closest('form')?.querySelector('button[type=submit]');if(send)send.disabled=i.disabled||i.readOnly||!i.value.trim()||i.value.length>1000;i.style.height='auto';i.style.height=Math.min(120,Math.max(58,i.scrollHeight))+'px';const error=i.closest('form')?.querySelector('.v34-chat-input-error');if(error){error.hidden=i.value.length<=1000;error.textContent='메시지는 1,000자까지 입력할 수 있어요.';}}if(i.id==='v38-report-detail'&&S.report)S.report.detail=i.value;if(S.clip&&i.id.startsWith('v38-clip-')){const k=i.id.slice(9);if(['title','start','end'].includes(k))S.clip[k]=i.value;if(k==='duration'){const a=parse(S.clip.start);S.clip.duration=Number(i.value);if(Number.isFinite(a)){S.clip.end=clock(Math.min(S.clip.source.end,a+S.clip.duration));F.dialog.querySelector('#v38-clip-end').value=S.clip.end;F.dialog.querySelector('output').textContent=(parse(S.clip.end)-a)+'초';}}}},true);
window.addEventListener('submit',ev=>{
if(ev.target.id==='v38-chat-form'){stop(ev);const input=ev.target.querySelector('textarea'),r=room(chatKey());if(!F.sessionLoggedIn||input.disabled||input.readOnly||!input.value.trim()||input.value.length>1000||F.v34Chat.composing)return;const text=input.value.trim(),reply=r.reply;r.draft='';r.reply=null;input.value='';F.chatDraft='';send(text,reply);}
if(ev.target.id==='v38-report-form'){stop(ev);const d=S.report;d.detail=F.dialog.querySelector('#v38-report-detail').value;if(!d.reason||(d.reason==='기타'&&!d.detail.trim())){d.error=!d.reason?'신고 사유를 선택하세요.':'상세 내용을 입력하세요.';F.render();return;}if(d.status==='sending')return;d.status='sending';d.error='';F.render();setTimeout(()=>{const fault=S.faults.report;delete S.faults.report;d.status=fault==='unknown'?'unknown':fault?'failed':'sent';if(S.report===d&&F.screen==='report-content')F.render();},650);}
if(ev.target.id==='v38-clip-form'){stop(ev);const d=S.clip;for(const k of ['title','start','end'])d[k]=F.dialog.querySelector('#v38-clip-'+k).value.trim();const a=parse(d.start),b=parse(d.end);d.error=!d.title?'클립 제목을 입력하세요.':!Number.isFinite(a)||!Number.isFinite(b)?'시간을 시:분:초 형식으로 입력하세요.':b<=a?'종료는 시작 이후로 설정하세요.':b-a>60?'클립은 60초까지 만들 수 있어요.':a<d.source.start||b>d.source.end?'원본의 재생 가능한 구간 안에서 선택하세요.':'';if(d.error){F.render();return;}d.duration=b-a;d.status='processing';const token=++d.token;F.render();setTimeout(()=>{if(token!==d.token)return;if(S.faults.clip){delete S.faults.clip;d.status='failed';}else{d.createdId=publishClip({title:d.title,start:a,end:b,originalId:d.source.id}).id;d.status='done';}if(F.screen==='clip-create')F.render();},650);}
if(ev.target.id==='v38-comment-form'){stop(ev);const input=F.root.querySelector('#v38-comment'),p=S.posts.get(channel())?.find(p=>p.id===S.postId),text=input.value.trim();if(!text||text.length>500||S.faults.comment){const error=F.root.querySelector('#v38-comment-error');error.hidden=false;error.textContent=S.faults.comment?'댓글을 등록하지 못했어요. 다시 시도하세요.':'댓글을 1~500자로 입력하세요.';delete S.faults.comment;input.focus();return;}p.comments.unshift({id:'comment-'+Date.now(),name:F.nickname,authorId:String(F.accountDesign?.savedProfile?.id||'viewer-self'),text});S.commentDrafts.set(p.id,'');F.render();}
},true);
window.addEventListener('click',ev=>{const b=ev.target.closest?.('button');if(!b||b.disabled)return;const id=b.dataset.v38Content||b.closest('.v3-card')?.dataset.v38Content;if(id&&['watch','vod-watch','clip-watch'].includes(b.dataset.go)){stop(ev);openContent(id);return;}if(b.dataset.action==='v33-viewer-notification'){stop(ev);const i=+b.dataset.index;F.v33Viewer.read.add(i);if(i===2){F.selectedBroadcast=3;F.channelTab='방송 일정';F.navigate('channel');}else openContent(i===1?'vod-1-0':'live-0');return;}
if(b.dataset.action==='v33-viewer-remind'&&!F.sessionLoggedIn){stop(ev);F.authReturn='channel';F.navigate('login');return;}
if(b.dataset.key==='share-option'&&F.screen==='share'){stop(ev);F.openChoice(b,['현재 방송','현재 재생 시점부터'],F.values['share-option']||'현재 방송',v=>{F.values['share-option']=v;F.render();});return;}
const action=b.dataset.action||'';if(!action.startsWith('v38-viewer-')||action.startsWith('v38-viewer-help-'))return;stop(ev);const a=action.slice(11);
if(a==='page'){S.pages[b.dataset.key]=Math.max(0,+b.dataset.page||0);F.render();F.root.querySelector('h1,h2')?.scrollIntoView({block:'start'});}
else if(a==='sort')F.openChoice(b,['최신순','인기순'],F.v33Viewer.sort[b.dataset.kind]||'최신순',v=>{F.v33Viewer.sort[b.dataset.kind]=v;S.pages[b.dataset.kind]=0;F.render();});
else if(a==='search-type'){F.searchType=b.dataset.type;S.pages={};F.render();}
else if(a==='clear-search'){F.searchQuery='';F.render();}
else if(a==='channel-posts'){F.channelTab='게시글';S.postId=null;F.writeUrl(true);F.render();}
else if(a==='post-open'){S.postId=b.dataset.id;F.render();}
else if(a==='post-back'){S.postId=null;F.render();}
else if(a==='comments-page'){S.commentPages[S.postId]=Math.max(0,+b.dataset.page);F.render();}
else if(a==='comment-clear'){S.commentDrafts.set(S.postId,'');F.root.querySelector('#v38-comment').value='';}
else if(a==='comment-delete'){S.deleteCommentId=b.dataset.id;dialog('댓글을 삭제할까요?','<p>삭제한 댓글은 복구할 수 없어요.</p>',btn('취소','dialog-close')+btn('삭제','comment-delete-confirm','','danger'),'comment-delete');}
else if(a==='comment-delete-confirm'){const p=S.posts.get(channel())?.find(p=>p.id===S.postId),c=p?.comments.find(c=>c.id===S.deleteCommentId);if(c){c.deleted=true;c.text='삭제된 댓글이에요.';}S.deleteCommentId=null;F.closeModal();F.render();}
else if(a==='report-comment'){const p=S.posts.get(channel())?.find(p=>p.id===S.postId),m=p?.comments.find(c=>c.id===b.dataset.id);beginReport(target(m));}
else if(a==='participants')participants();
else if(a==='dialog-close')F.closeModal();
else if(a==='mention'||a==='emoji-add'){const r=room(chatKey()),draft=r.draft+(a==='mention'?'@'+b.dataset.name+' ':b.dataset.emoji);F.closeModal();r.draft=draft;F.chatDraft=draft;const input=F.root.querySelector('#chat-message');if(input)input.value=draft;F.render();F.root.querySelector('#chat-message')?.focus();}
else if(a==='emoji')dialog('이모티콘','<div class="v38-emoji">'+['😀','😊','👏','💚','👍','🎉','👀','☕'].map(x=>btn(x,'emoji-add','','','data-emoji="'+x+'" aria-label="'+x+'"')).join('')+'</div>',btn('닫기','dialog-close'),'emoji');
else if(a==='message-menu'){const line=b.closest('.chat-line'),name=line.querySelector('strong')?.textContent||'사용자',text=line.querySelector('span')?.textContent||'';S.messageTarget={id:'line-'+chatKey()+'-'+b.dataset.line,name,text};F.openChoice(b,['답글','언급','신고'],null,v=>{if(v==='신고')beginReport(target(S.messageTarget));else{const r=room(chatKey());if(v==='답글')r.reply=S.messageTarget;else r.draft+='@'+name+' ';F.render();F.root.querySelector('#chat-message')?.focus();}});}
else if(a==='reply-cancel'){room(chatKey()).reply=null;F.render();}
else if(a==='message-retry'){const m=room(chatKey()).pending.find(m=>m.id===b.dataset.id);if(m)send(m.text,m.reply,m.id);}
else if(a==='chat-reconnect'){room(chatKey()).mode='open';F.render();}
else if(a==='chat-follow'){F.v33Viewer.following.add(channel());room(chatKey()).mode='open';F.render();}
else if(a==='report-reason')F.openChoice(b,['부적절한 콘텐츠','도배 및 광고','권리 침해','개인정보 노출','기타'],S.report.reason,v=>{S.report.reason=v;S.report.error='';F.render();});
else if(a==='close-report'){S.report=null;F.closeModal();}
else if(a==='report-status'){S.report.status='sent';F.render();}
else if(a==='clip-cancel'){if(S.clip)S.clip.token++;F.closeModal();S.clip=null;}
else if(a==='clip-watch'){const id=S.clip.createdId;F.closeModal();openContent(id);}
},true);
window.addEventListener('keydown',ev=>{const t=ev.target.closest?.('.v38-filter-tabs [role="tab"]');if(!t||!['ArrowLeft','ArrowRight','Home','End'].includes(ev.key))return;stop(ev);const all=[...t.parentNode.children],i=all.indexOf(t),n=ev.key==='Home'?0:ev.key==='End'?all.length-1:(i+(ev.key==='ArrowRight'?1:all.length-1))%all.length;S.pages={};F.searchType=all[n].dataset.type;F.render();F.root.querySelector('.v38-filter-tabs [data-type="'+F.searchType+'"]')?.focus();},true);

/* Public help uses the same route as policy, with a clear way back to policy documents. */
const policyPage=F.pages.policy;
S.help={query:'',topic:null,policy:false};
const guides=[
 {id:'watch',title:'방송 시청',icon:'play',body:'홈에서 보고 싶은 방송을 선택하세요. 영상 위를 클릭하면 재생과 일시정지를 전환할 수 있어요.\n지난 구간을 보고 있다면 실시간 버튼으로 현재 방송에 돌아갈 수 있어요. 영상이 멈췄다면 재생 화면에서 다시 시도하세요.'},
 {id:'quality',title:'화질과 소리',icon:'gear',body:'플레이어의 화질 메뉴에서 자동 또는 원하는 화질을 선택하세요. 자동은 시청 환경에 맞는 화질을 선택하는 설정이에요.\n스피커 버튼으로 소리를 끄고 켤 수 있어요. 모바일에서 소리가 나지 않으면 소리 켜기를 누르세요.'},
 {id:'broadcast',title:'방송 시작과 종료',icon:'live',body:'방송하기에서 공유할 프로그램 창이나 모니터를 선택하세요. 방송 정보와 오디오를 확인한 뒤 방송 시작을 누르세요.\n공유 대상을 고르는 것만으로 방송은 시작되지 않아요. 종료할 때는 방송 종료에서 녹화 보관 여부를 확인하세요.'},
 {id:'chat',title:'채팅과 닉네임',icon:'chat',body:'채팅 입력 영역의 닉네임에서 표시 이름을 바꿀 수 있어요. 이름을 바꿔도 이전에 보낸 메시지의 이름은 유지돼요.\n메시지 메뉴에서 답글과 신고를 사용할 수 있어요. 전송 실패가 표시된 메시지는 재전송할 수 있어요.'},
 {id:'history',title:'시청 기록 관리',icon:'history',body:'시청 기록에서 제목이나 채널 이름을 검색하세요. 종류와 기간을 함께 선택하면 오래된 기록도 찾을 수 있어요.\n선택한 기록을 삭제하거나 기록 저장을 일시중지할 수 있어요. 기록을 지워도 원본 영상과 채널은 삭제되지 않아요.'},
 {id:'account',title:'계정과 멤버십',icon:'user',body:'내 설정에서 프로필과 로그인 수단을 관리하세요. 마지막 로그인 수단은 다른 수단을 연결한 뒤 해제할 수 있어요.\n멤버십에서 이용 종료일과 자동 갱신 상태를 확인하세요. 결제 내역에서는 선택한 거래의 환불 요청과 처리 상태를 확인할 수 있어요.'}
];
F.pages.policy=state=>{
 if(S.help.policy)return '<div class="v38-help-back">'+btn('이용 안내','help-back','arrow','ghost')+'</div>'+policyPage(state);
 const topic=guides.find(g=>g.id===S.help.topic),q=S.help.query.trim().toLocaleLowerCase(),rows=guides.filter(g=>(g.title+' '+g.body).toLocaleLowerCase().includes(q));
 return F.page('도움말',topic?'<section class="v38-help-article">'+btn('이용 안내','help-back','arrow','ghost')+'<h2>'+e(topic.title)+'</h2>'+topic.body.split('\n').map(p=>'<p>'+e(p)+'</p>').join('')+'</section>':'<section class="v38-help"><form id="v38-help-search" role="search"><label class="sr-only" for="v38-help-query">도움말 검색</label><input id="v38-help-query" type="search" maxlength="100" placeholder="궁금한 내용을 검색하세요." value="'+e(S.help.query)+'"><button type="submit" aria-label="도움말 검색">'+F.icon('search')+'</button></form>'+(rows.length?'<div class="v38-help-grid">'+rows.map(g=>btn('<span>'+F.icon(g.icon)+'</span><strong>'+e(g.title)+'</strong>','help-topic','','','data-topic="'+g.id+'"')).join('')+'</div>':F.empty('검색한 안내가 없어요','','검색어 지우기','v38-viewer-help-clear','search'))+'</section>',btn('이용 및 콘텐츠 정책','help-policy','file','ghost'));
};
window.addEventListener('click',ev=>{const b=ev.target.closest?.('button[data-action^="v38-viewer-help-"]');if(!b)return;stop(ev);const a=b.dataset.action;if(a.endsWith('topic'))S.help.topic=b.dataset.topic;else if(a.endsWith('policy'))S.help.policy=true;else if(a.endsWith('clear'))S.help.query='';else{S.help.topic=null;S.help.policy=false;}F.render();},true);
window.addEventListener('submit',ev=>{if(ev.target.id!=='v38-help-search')return;stop(ev);S.help.query=ev.target.querySelector('input').value;F.render();},true);

F.readUrl();F.render();if(window.FRAME_PROTOTYPE)window.FRAME_PROTOTYPE.navigate=F.navigate;
})();
